import { Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { catchError, EMPTY, Subject, switchMap } from 'rxjs';

@Component({
  selector: 'app-checkout',
  template: `<button (click)="placeOrder$.next()">Place order</button>`,
})
export class Checkout {
  private readonly api = inject(OrderApi);
  readonly placeOrder$ = new Subject<void>();

  constructor() {
    this.placeOrder$
      .pipe(
        // A 2nd click aborts the 1st POST, which may already be saved
        switchMap(() =>
          this.api.placeOrder().pipe(catchError(() => EMPTY)),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((order) => console.log('Created', order.id));
  }
}

import { Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { catchError, EMPTY, exhaustMap, Subject } from 'rxjs';

@Component({
  selector: 'app-checkout',
  template: `<button (click)="placeOrder$.next()">Place order</button>`,
})
export class Checkout {
  private readonly api = inject(OrderApi);
  readonly placeOrder$ = new Subject<void>();

  constructor() {
    this.placeOrder$
      .pipe(
        // Clicks while an order is pending are ignored
        exhaustMap(() =>
          this.api.placeOrder().pipe(catchError(() => EMPTY)),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((order) => console.log('Created', order.id));
  }
}

