import { FormControl } from '@angular/forms';
import { concatMap, debounceTime, Observable } from 'rxjs';

export function autosave(
  text: FormControl<string>,
  save: (value: string) => Observable<void>,
) {
  return text.valueChanges.pipe(
    debounceTime(800),
    // Each save waits for the previous one to finish
    concatMap((value) => save(value)),
  );
}
